mapper.select:
SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( '01', '02', '03', '05' )
AND MDATE <= STR_TO_DATE(#{sysDate},'%Y-%m-%d')
)

mapper.update:
UPDATE ETR_ENTRUST SET ENTRUST_STATUS = '06' WHERE ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( '01', '02', '03', '05' )
AND MDATE <= STR_TO_DATE(#{sysDate},'%Y-%m-%d')
)
